def build(vid, spec):
    b = spec['base']
    return build_kw(title="الدخان " + vid, review='پیش‌نویسِ منبع‌محور؛ ' + spec['note'],
                    notes=b['notes'], context=b['context'], classical=b['classical'],
                    modern=b['modern'], critical=b['critical'], research=b['research'], ext=spec['ext'])


